import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
import { t } from '../common/text';

/** A quote while it's being played: the words and the four faces, nothing more. */

/** A quote with its answer: one the member answered, or yesterday's. */

export function call(method, path, body) {
  return app.request({
    method,
    url: app.forum.attribute('apiUrl') + '/who-said-it' + path,
    body,
    errorHandler: error => {
      const code = error?.response?.errors?.[0]?.code;
      const known = ['wsi_closed', 'wsi_withdrawn', 'wsi_no_quiz', 'wsi_making', 'wsi_bad_choice', 'wsi_not_shown'];
      app.alerts.show({
        type: 'error'
      }, known.includes(code) ? t(`forum.errors.${code}`) : t('forum.errors.generic'));
      throw error;
    }
  });
}

/** People arrive as one compact list; the store lets Avatar draw them the usual way. */
export function pushUsers(users) {
  for (const user of users) {
    if (app.store.getById('users', String(user.id))) continue;
    app.store.pushObject({
      type: 'users',
      id: String(user.id),
      attributes: {
        username: user.username,
        displayName: user.displayName,
        slug: user.slug,
        avatarUrl: user.avatarUrl
      }
    });
  }
}
export function user(id) {
  return id ? app.store.getById('users', String(id)) : null;
}

/** "Tue, Nov 10" for a quiz day (a plain date, so read it as one). */
export function dayLabel(date) {
  const [y, mo, d] = date.split('-').map(Number);
  try {
    return new Intl.DateTimeFormat(app.translator.getLocale() || undefined, {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    }).format(new Date(y, mo - 1, d));
  } catch {
    return date;
  }
}
export const SQUARES = {
  G: '🟩',
  Y: '🟨',
  R: '🟥',
  V: '⬜',
  '-': '⬛'
};

/** The result as text, to paste anywhere. */
export function shareText(date, me, count) {
  const grid = me.grid.padEnd(count, '-').slice(0, count).split('').map(l => SQUARES[l] || '⬛').join('');
  const lines = [extractText(t('forum.share.title', {
    forum: app.forum.attribute('title'),
    date: dayLabel(date)
  })), `${grid} ${me.correct}/${count} · ${me.score}`];
  if (me.streak > 1) lines.push(extractText(t('forum.share.streak', {
    count: me.streak
  })));
  lines.push(new URL(app.route('who-said-it'), window.location.origin).href);
  return lines.join('\n');
}